drop policy if exists "Authenticated users can view active emergency contacts" on public.campus_emergency_contacts; create policy "Authenticated users can view active emergency contacts" on public.campus_emergency_contacts for select to authenticated using (is_active and (campus is null or campus = public.get_user_campus((select auth.uid())) or public.is_super_admin((select auth.uid())) or public.is_campus_admin((select auth.uid()))));